18	// registerNodeZoneWatcher registers a background job that watches Table[LocalNode] and
19	// refreshes the frontends with a configured TrafficDistribution to re-select backends.
20	func registerNodeZoneWatcher(jg job.Group, p zoneWatcherParams) {
21		if p.Config.EnableServiceTopology {
22			jg.Add(job.OneShot("zone-watcher", zoneWatcher{p}.run))
23		}
24	}
25	
26	type zoneWatcherParams struct {
27		cell.In
28	
29		Config loadbalancer.Config
30		Writer *Writer
31		Nodes  statedb.Table[*node.LocalNode]
32	}
33	
34	type zoneWatcher struct {
35		zoneWatcherParams
36	}
37	
38	func (zw zoneWatcher) run(ctx context.Context, health cell.Health) error {
39		var oldZone string
40		for {
41			txn := zw.Writer.WriteTxn()
42			node, _, watch, found := zw.Nodes.GetWatch(txn, node.LocalNodeQuery)
43			updated := false
44			if found {
45				newZone := node.Labels[corev1.LabelTopologyZone]
46				if newZone != oldZone {
47					// Refresh all frontends associated with topology-aware services
48					// as the backend selection might change.
49					for fe := range zw.Writer.fes.All(txn) {
50						if fe.Service.TrafficDistribution != loadbalancer.TrafficDistributionDefault {
51							fe = fe.Clone()
52							zw.Writer.refreshFrontend(txn, fe)
53							zw.Writer.fes.Insert(txn, fe)
54							updated = true
55						}
56					}
57				}
58			}
59			if updated {
60				txn.Commit()
61			} else {
62				txn.Abort()
63			}
64			select {
65			case <-ctx.Done():
66				return nil
67			case <-watch:
68			}
69		}
70	}
